    "hBP04-067": "Arts: Ajimaru! Ajimaru!\nCost: 1 yellow\nPower: 20\n\nArts: Sup! I'm Oozora Subaru from hololive 2nd Generation!!\nCost: 1 yellow, 2 any color\nPower: 60\n\nExtra: You may include any number of this holomem in the deck",
    "hBP05-075": "Choose 1 of your holomem. During this turn, the chosen holomem requires -2 colorless for its baton pass. Restore 20 HP to the chosen holomem.",
